    fn expr_or_ordinal(
        &mut self,
        e: &SQLExpr,
        exprs: &[Expr],
        selected: Option<&[Expr]>,
        schema: Option<&Schema>,
        clause: &str,
    ) -> PolarsResult<Expr> {
        match e {
            SQLExpr::UnaryOp {
                op: SQLUnaryOperator::Minus,
                expr,
            } if matches!(
                **expr,
                SQLExpr::Value(ValueWithSpan {
                    value: SQLValue::Number(_, _),
                    ..
                })
            ) =>
            {
                if let SQLExpr::Value(ValueWithSpan {
                    value: SQLValue::Number(ref idx, _),
                    ..
                }) = **expr
                {
                    Err(polars_err!(
                    SQLSyntax:
                    "negative ordinal values are invalid for {}; found -{}",
                    clause,
                    idx
                    ))
                } else {
                    unreachable!()
                }
            },
            SQLExpr::Value(ValueWithSpan {
                value: SQLValue::Number(idx, _),
                ..
            }) => {

                let idx = idx.parse::<usize>().map_err(|_| {
                    polars_err!(
                        SQLSyntax:
                        "negative ordinal values are invalid for {}; found {}",
                        clause,
                        idx
                    )
                })?;


                let cols = if let Some(cols) = selected {
                    cols
                } else {
                    exprs
                };
                Ok(cols
                    .get(idx - 1)
                    .ok_or_else(|| {
                        polars_err!(
                            SQLInterface:
                            "{} ordinal value must refer to a valid column; found {}",
                            clause,
                            idx
                        )
                    })?
                    .clone())
            },
            SQLExpr::Value(v) => Err(polars_err!(
                SQLSyntax:
                "{} requires a valid expression or positive ordinal; found {}", clause, v,
            )),
            _ => {


                let mut expr = parse_sql_expr(e, self, schema)?;
                if matches!(e, SQLExpr::CompoundIdentifier(_)) {
                    if let Some(schema) = schema {
                        expr = expr.map_expr(|ex| match &ex {
                            Expr::Column(name) => {
                                let prefixed = format!("__POLARS_ORIG_{}", name.as_str());
                                if schema.contains(prefixed.as_str()) {
                                    col(prefixed)
                                } else {
                                    ex
                                }
                            },
                            _ => ex,
                        });
                    }
                }
                Ok(expr)
            },
        }
    }

    pub(crate) fn record_joined_aliases(
        &mut self,
        r_name: &str,
        right_relations: &[String],
        left_schema: &Schema,
        right_schema: &Schema,
        joined_schema: &Schema,
    ) -> PolarsResult<()> {
        let renamed: PlHashMap<String, String> = right_schema
            .iter_names()
            .filter(|name| left_schema.contains(name))
            .filter_map(|name| {
                let aliased_name = format!("{name}:{r_name}");
                joined_schema
                    .contains(aliased_name.as_str())
                    .then(|| (name.to_string(), aliased_name))
            })
            .collect();
        for relation in right_relations {
            if relation == r_name {
                continue;
            }
            let Some(mut relation_lf) = self.get_relation_frame(relation)? else {
                continue;
            };
            let relation_schema = self.get_frame_schema(&mut relation_lf)?;
            let aliases = self.joined_aliases.entry(relation.clone()).or_default();
            for name in aliases.values_mut() {
                if let Some(aliased_name) = renamed.get(name.as_str()) {
                    *name = aliased_name.clone();
                }
            }
            for (name, aliased_name) in &renamed {
                if relation_schema.contains(name) && !aliases.contains_key(name) {
                    aliases.insert(name.clone(), aliased_name.clone());
                }
            }
        }
        self.joined_aliases.insert(r_name.to_string(), renamed);
        Ok(())
    }

