                using_cols: from
                    .iter()
                    .flat_map(|tbl_expr| &tbl_expr.joins)
                    .filter_map(|join| {
                        let cols = get_using_cols(&join.join_operator)?;
                        let r_name = get_table_name(&join.relation)?;
                        Some(cols.map(move |c| (r_name.clone(), c)))
                    })
