fn finish_ie_join(
    left: &DataFrame,
    right: &DataFrame,
    mut left_idx: IdxCa,
    mut right_idx: IdxCa,
    emit_unmatched: EmitUnmatched,
    suffix: Option<PlSmallStr>,
    slice: Option<(i64, usize)>,
) -> PolarsResult<DataFrame> {
